"""Native battery cassette with fixed pack details and shared rail attachment width."""
class FrameCassetteIntent(FrameRailIntent):
 def parameters(self):
  super().parameters();g=self.g
  values={'cassette_length':140,'cassette_height':69.5,'cassette_wall':2,'cassette_corner_radius':12,'cassette_half_y':'frame_half_y-5 mm','cassette_guide_y':'frame_half_y-11.5 mm','cassette_guide_bridge_y':'frame_half_y-8 mm','cassette_access_boss_x':50,'cassette_access_boss_y':'frame_half_y-8.75 mm','cassette_mount_boss_y':'frame_half_y-7.85 mm','cassette_nut_y':'frame_half_y-8.2 mm','cassette_nut_nominal_af':5.5,'cassette_nut_af_allowance':.3,'cassette_nut_nominal_thickness':2.4,'cassette_nut_axial_allowance':.4,'cassette_hole_process_compensation':0,'cassette_access_pilot_nominal':2.5,'cassette_pilot_process_compensation':0,'cassette_access_pilot_diameter':'cassette_access_pilot_nominal+cassette_pilot_process_compensation','cassette_m3_clearance':'frame_m3_nominal+robot_fastener_diametral_allowance+cassette_hole_process_compensation','cassette_nut_af_process_compensation':0,'cassette_nut_axial_process_compensation':0,'cassette_nut_pocket_af':'cassette_nut_nominal_af+cassette_nut_af_allowance+cassette_nut_af_process_compensation','cassette_nut_pocket_depth':'cassette_nut_nominal_thickness+cassette_nut_axial_allowance+cassette_nut_axial_process_compensation'}
  for name,value in values.items():g.parameter(name,value,comment='Battery support geometry or independent M3 nut envelope. Pack and connector selection remains separate; allowances reproduce the frozen model.')
 def mirrored_collection(self,bodies,plane,label):
  c=self.c;before={b.entityToken for b in c.bRepBodies};objects=core.ObjectCollection.create()
  for body in bodies:objects.add(body)
  inp=c.features.mirrorFeatures.createInput(objects,plane);inp.isCombine=False;f=c.features.mirrorFeatures.add(inp);f.name=label;new=[b for b in c.bRepBodies if b.entityToken not in before];assert len(new)==len(bodies);return new
 def opposed_holes(self,body,x,y,z,diameter,depth,label):
  g=self.g;c=self.c;plane=g.plane(c.xZConstructionPlane,y,label+' datum');sk=self.circles_line(plane,[x,'-('+x+')'],'-('+z+')',diameter,label+' positive side profile');f=g.extrude_all(sk,depth,label+' positive side tools');tools=list(f.bodies);assert len(tools)==2;tools+=self.mirrored_collection(tools,c.xZConstructionPlane,label+' opposite side');return self.cut(body,tools,label)
 def build(self):
  self.parameters();g=self.g;c=self.c
  body=self.box('cassette_length','2*cassette_half_y','cassette_height','0 mm','0 mm','-cassette_height/2','Rounded battery enclosure','cassette_corner_radius');inner=self.box('cassette_length-2*cassette_wall','2*cassette_half_y-2*cassette_wall','cassette_height-cassette_wall+2.5 mm','0 mm','0 mm','(-cassette_height+cassette_wall+2.5 mm)/2','Open battery cavity','cassette_corner_radius-cassette_wall');body=self.cut(body,[inner],'Constant nominal enclosure wall')
  guide=self.box('134 mm','5 mm','61 mm','0 mm','cassette_guide_y','-36 mm','One integral battery guide','2 mm');plane=g.plane(c.xZConstructionPlane,'cassette_guide_y-3.5 mm','Guide opening datum');sk=g.rounded_rectangle(plane,'112 mm','45 mm','7 mm','34 mm','Rounded guide window');tool=g.extrude(sk,'7 mm','Guide window tool').bodies.item(0);guide=self.cut(guide,[tool],'Open guide for weight and access');bridge=self.box('9 mm','6 mm','54 mm','60 mm','cassette_guide_bridge_y','-36 mm','Guide-to-wall bridge','.5 mm');guide=self.join(guide,[bridge,self.reflected(bridge,c.yZConstructionPlane,'Opposite end guide bridge')],'Supported guide frame');body=self.join(body,[guide,self.reflected(guide,c.xZConstructionPlane,'Opposed pack guide')],'Two integral pack guide frames')
  plane=g.plane(c.yZConstructionPlane,'-56 mm','Upper guide gusset datum');sk=c.sketches.add(plane);sk.name='Broad upper battery guide gusset';coordinates=[('20.5 mm','cassette_half_y'),('5.5 mm','cassette_half_y'),('5.5 mm','cassette_half_y-9 mm'),('11.5 mm','cassette_half_y-9 mm')];points=[g.skeleton_point(sk,*pair) for pair in coordinates];g.point_dimensions(sk,points[0],*coordinates[0]);g.point_dimensions(sk,points[1],coordinates[1][0],None);sk.geometricConstraints.addHorizontalPoints(points[0],points[1]);g.point_dimensions(sk,points[2],None,coordinates[2][1]);sk.geometricConstraints.addVerticalPoints(points[1],points[2]);g.point_dimensions(sk,points[3],coordinates[3][0],None);sk.geometricConstraints.addHorizontalPoints(points[2],points[3])
  for i,p in enumerate(points):sk.sketchCurves.sketchLines.addByTwoPoints(p,points[(i+1)%4])
  assert sk.profiles.count==1;gusset=g.extrude(sk,'112 mm','Continuous upper guide gusset').bodies.item(0);body=self.join(body,[gusset,self.reflected(gusset,c.xZConstructionPlane,'Opposed upper guide gusset')],'Broad enclosure-to-guide supports')
  boss=self.box('9 mm','7.5 mm','9 mm','cassette_access_boss_x','cassette_access_boss_y','-59 mm','Access panel pilot boss','.5 mm');body=self.join(body,self.four(boss,'Access panel boss'),'Four integral access panel bosses');body=self.opposed_holes(body,'cassette_access_boss_x','frame_half_y-13 mm','-59 mm','cassette_access_pilot_diameter','9 mm','Four access panel pilot holes')
  boss=self.box('12 mm','10.3 mm','16 mm','frame_deck_mount_x','cassette_mount_boss_y','-8 mm','Frame attachment boss','.7 mm');body=self.join(body,self.four(boss,'Frame attachment boss'),'Four supported frame attachments');body=self.opposed_holes(body,'frame_deck_mount_x','frame_half_y-15 mm','-6 mm','cassette_m3_clearance','15 mm','Common cassette-to-rail screw clearances')
  pocket=self.box('cassette_nut_pocket_af','cassette_nut_pocket_depth','12.4 mm','frame_deck_mount_x','cassette_nut_y','-3.2 mm','Top-loading standard nut pocket');body=self.cut(body,self.four(pocket,'Captive nut pocket'),'Four accessible M3 nut pockets');assert c.bRepBodies.count==1;return body
